// Map Apify job rows to an Airtable records payload (max 10).
// Common field names are tried in order; empty strings if a field is missing.
const pick = (obj, keys) => {
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return '';
};
const records = items.slice(0, 10).map((item) => {
  const j = item.json || {};
  return {
    fields: {
      Title: pick(j, ['title', 'jobTitle', 'name']),
      Company: pick(j, ['company', 'companyName', 'companySlug']),
      Location: pick(j, ['location', 'locations', 'workplace']),
      Department: pick(j, ['department', 'team', 'departments']),
      URL: pick(j, ['url', 'jobUrl', 'absoluteUrl', 'applyUrl']),
      Posted: pick(j, ['publishedAt', 'postedAt', 'absoluteDate', 'firstPublishedAt', 'updatedAt']),
      Source: 'greenhouse',
    },
  };
});
return [{ json: { records } }];
